/**
 * @summary Set tip for collaborator (organizer only)
 */
export const getSetTipUrl = (id: string, userId: string) => {
  return `/api/events/${id}/tips/${userId}`;
};

export const setTip = async (
  id: string,
  userId: string,
  setTipBody: SetTipBody,
  options?: RequestInit,
): Promise<Tip> => {
  return customFetch<Tip>(getSetTipUrl(id, userId), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(setTipBody),
  });
};

export const getSetTipMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof setTip>>,
    TError,
    { id: string; userId: string; data: BodyType<SetTipBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof setTip>>,
  TError,
  { id: string; userId: string; data: BodyType<SetTipBody> },
  TContext
> => {
  const mutationKey = ["setTip"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof setTip>>,
    { id: string; userId: string; data: BodyType<SetTipBody> }
  > = (props) => {
    const { id, userId, data } = props ?? {};

    return setTip(id, userId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type SetTipMutationResult = NonNullable<
  Awaited<ReturnType<typeof setTip>>
>;
export type SetTipMutationBody = BodyType<SetTipBody>;
export type SetTipMutationError = ErrorType<unknown>;

